signs = [list(map(int, l.split())) for l in open('signs.txt') if l.strip()]
s = [float(x) for x in open('sum.txt').read().split()]
n = len(signs)
d = len(s)

def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def solve(A, b):
    k = len(A)
    M = [[dot(A[i], A[j]) for j in range(k)] + [dot(A[i], b)] for i in range(k)]
    for c in range(k):
        p = max(range(c, k), key=lambda r: abs(M[r][c]))
        M[c], M[p] = M[p], M[c]
        if abs(M[c][c]) < 1e-12:
            return None
        for r in range(k):
            if r != c:
                f = M[r][c] / M[c][c]
                for j in range(c, k + 1):
                    M[r][j] -= f * M[c][j]
    return [M[i][k] / M[i][i] for i in range(k)]

def resid(sel):
    c = solve([signs[i] for i in sel], s)
    if c is None:
        return None, None
    r = s[:]
    for ci, i in zip(c, sel):
        for t in range(d):
            r[t] -= ci * signs[i][t]
    return sum(x * x for x in r), r

sel = []
r = s[:]
for step in range(16):
    best = max((abs(dot(signs[i], r)), i) for i in range(n) if i not in sel)[1]
    sel.append(best)
    e, r = resid(sel)
    print(step + 1, best + 1, e)

with open('players.txt', 'w') as f:
    for i in sorted(sel):
        f.write(str(i + 1) + '\n')
print('selected', sorted(i + 1 for i in sel))
print('final residual squared', resid(sel)[0])
